const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={minutes:90,done:{fr:[],de:[]},reviews:{},large:false};try{const s=JSON.parse(localStorage.getItem('bh-progress'));if(s&&s.done&&Array.isArray(s.done.fr)&&Array.isArray(s.done.de))state={...state,...s};}catch{}
let view='today',language='fr',active=null,step=0,phraseIndex=0,passed=false,listeningPassed=false,recorder=null,recordUrl=null,stream=null;
function save(){try{localStorage.setItem('bh-progress',JSON.stringify(state));}catch{notice('Storage is unavailable. Export a backup from settings.');}}
function notice(t){$('#notice').textContent=t;$('#notice').style.display='block';clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>$('#notice').style.display='none',4500);}
function completed(l){return state.done[l].length;}function next(l){return COURSE[l].lessons.findIndex((_,i)=>!state.done[l].includes(i));}function flag(l){return `<span class="flag ${l}" aria-label="${COURSE[l].name}"></span>`;}function due(){return Object.entries(state.reviews).filter(([,r])=>r.due<=Date.now());}
function nav(v){view=v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#breadcrumb').textContent='Your learning space / '+({today:'Today',journey:'My journey',practice:'Practice studio',words:'My words',progress:'My progress'}[v]);render();}
function render(){document.documentElement.classList.toggle('large-text',state.large);let html='';if(view==='today')html=`<div class="welcome"><div><h1>A little today. A world tomorrow.</h1><p>Your next conversation starts with one small step.</p></div><span class="day-chip">◷ Day ${Math.min(150,Math.min(completed('fr'),completed('de'))+1)} of 150</span></div><section class="hero"><div class="hero-copy"><p class="eyebrow">YOUR EVERYDAY JOURNEY</p><h2>Small conversations.<br>A growing world.</h2><p>Meet people, order a drink, find your way.<br>Build your confidence, one lesson at a time.</p><span style="font-size:12px;color:#d4e7b0">✦ Two languages. Endless possibilities.</span></div><div class="hero-art"><img src="https://upload.wikimedia.org/wikipedia/commons/7/76/Rue_Buci_-_Paris_VI_%28FR75%29_-_2021-07-29_-_1.jpg" alt="Outdoor cafés and colourful awnings on Rue de Buci in Paris"><span class="photo-label">A little window into Paris</span></div></section><div class="section-head"><h2>Your lessons today</h2><span>YOUR PACE · ${state.minutes} MIN / DAY <button data-action="settings" aria-label="Change daily time">↗</button></span></div><div class="cards">${['fr','de'].map(l=>{let n=next(l),i=n<0?COURSE[l].lessons.length-1:n,d=COURSE[l].lessons[i];return `<article class="card ${l==='de'?'german':''}"><div class="language-head">${flag(l)}<div><h3>${COURSE[l].name}</h3><small>${l==='fr'?'Bonjour !':'Hallo!'}</small></div><span class="pill">A1 · BEGINNER</span></div><p class="eyebrow">${n<0?'AVAILABLE LESSONS COMPLETE · REVISIT':'DAY '+(i+1)+' · '+chapterName(i)}</p><h2>${d.title}</h2><p>${d.goal}</p><div class="tags"><span>◷ ${Math.round(state.minutes*35/90)} min suggested</span><span>♬ Listen</span><span>◉ Speak</span></div><button class="primary" data-lesson="${l}:${i}">${n<0?'Revisit lesson':'Start '+COURSE[l].name+' lesson'} <span>→</span></button></article>`}).join('')}</div><div class="bottom-grid"><section class="card review"><div class="icon-tile">↺</div><div><h3>A little review goes a long way</h3><p>${due().length?due().length+' phrases ready for another look.':'Your learned phrases will come back here.'}</p></div><button class="secondary" data-action="review">${due().length?'Review now':'Explore words'}</button></section><section class="card tip"><p class="eyebrow">A SMALL TIP</p><h3>Say it out loud. Even quietly.</h3><p>Your voice is part of learning. Give each new phrase a try.</p></section></div><p class="muted" style="font-size:12px;margin-top:24px">${COURSE.fr.lessons.length} complete learning days per language. Days ${COURSE.fr.lessons.length+1}–150 are a curriculum roadmap, with lessons still to come. <a href="https://commons.wikimedia.org/wiki/File:Rue_Buci_-_Paris_VI_(FR75)_-_2021-07-29_-_1.jpg" target="_blank" rel="noopener">Photo: Chabe01</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a> · cropped.</p>`;
if(view==='journey')html=`<h1>Your journey, one day at a time.</h1><p class="muted">Start from zero. Build toward everyday conversations. Take longer whenever you need.</p>${switcher()}<div class="phase"><h3>Foundations & everyday conversations</h3><p>${COURSE[language].lessons.length} complete lessons, including ${COURSE[language].lessons.filter(d=>d.checkpoint).length} conversation checkpoints. You can revisit any lesson.</p></div><div class="list">${COURSE[language].lessons.map((d,i)=>`<article class="list-row"><span class="number">${state.done[language].includes(i)?'✓':i+1}</span><div><h3>${d.title}${d.checkpoint?' · Speaking checkpoint':''}</h3><p>${d.goal}</p></div><button class="secondary" data-lesson="${language}:${i}">${state.done[language].includes(i)?'Revisit':'Learn'}</button></article>`).join('')}</div><div class="section-head"><h2>The full 150-day plan</h2><span>CURRICULUM ROADMAP</span></div>${PHASES.map(p=>`<section class="phase"><p class="eyebrow">DAYS ${p[0]}</p><h3>${p[1]}</h3><p>${p[2]}</p></section>`).join('')}<p class="muted">Lessons beyond day ${COURSE[language].lessons.length} are not available yet. The target is practical A2 skills, with optional B1 challenges; completion is not a language certification.</p>`;
if(view==='words'){let words=knownWords();html=`<h1>Little words. Growing confidence.</h1><p class="muted">Your phrases appear here after you complete a lesson. Listen, cover the answer, and try remembering.</p>${switcher()}${words.length?`<div class="list">${words.map(([p,e],i)=>`<article class="card word"><div><strong lang="${language}">${esc(p)}</strong><p>${esc(e)}</p></div><button class="secondary" data-say="${esc(p)}" data-lang="${language}" aria-label="Listen to ${esc(p)}">♬ Listen</button></article>`).join('')}</div>`:`<div class="empty"><h2>Your first words are waiting.</h2><p>Complete your first lesson to start your collection.</p><button class="primary" data-lesson="${language}:0">Learn your first hello</button></div>`}`;}
if(view==='practice')html=`<h1>Make a little noise.</h1><p class="muted">Listen closely. Try speaking. You don’t need to get it perfect.</p>${switcher()}<div class="cards"><section class="card"><div class="icon-tile">♬</div><h2 style="margin-top:20px">Listen & repeat</h2><p>Hear a short exchange, then practise your part. Record and replay your own voice.</p><button class="primary" data-lesson="${language}:0">Open speaking practice →</button></section><section class="card"><div class="icon-tile">↺</div><h2 style="margin-top:20px">Bring it back</h2><p>${due().length} phrases due across both languages. Try remembering before revealing the answer.</p><button class="primary" data-action="review">Start a review →</button></section></div><section class="card resource"><p class="eyebrow">WATCH & LISTEN · FREE EXTERNAL RESOURCE</p><h2>${language==='de'?'Meet Nico. Hear real German.':'Discover French with TV5MONDE.'}</h2><p>${language==='de'?'Watch the opening minute. Listen for greetings you recognise. Replay with captions, then say one greeting aloud. The full film goes beyond this first lesson.':'Choose an A1 beginner video. Watch once, note one greeting or familiar word, then replay with the transcript. Some videos suit older learners; choose a suitable topic.'}</p>${language==='de'?'<button class="secondary" data-action="video">Load German video</button><div id="video-slot"></div>':''}<p><a href="${language==='de'?'https://www.youtube.com/watch?v=4-eDoThe6qo':'https://apprendre.tv5monde.com/en'}" target="_blank" rel="noopener">${language==='de'?'Watch Nicos Weg on DW’s YouTube channel':'Open free French video lessons'} ↗</a></p><p style="font-size:12px">External videos require internet and follow the provider’s privacy settings. If an embed is unavailable, use the link.</p></section>`;
if(view==='progress'){let total=completed('fr')+completed('de');html=`<h1>Look how far you’ve come.</h1><p class="muted">Small efforts add up. Your learning record is saved on this device.</p><div class="stats"><div class="card stat"><strong>${total}</strong><p>Lessons completed</p></div><div class="card stat"><strong>${Object.keys(state.reviews).length}</strong><p>Phrases introduced</p></div><div class="card stat"><strong>${due().length}</strong><p>Phrases due for review</p></div></div><div class="cards" style="margin-top:24px">${['fr','de'].map(l=>`<section class="card"><div class="language-head">${flag(l)}<h2>${COURSE[l].name}</h2></div><p>${completed(l)} of ${COURSE[l].lessons.length} lessons completed</p><progress max="${COURSE[l].lessons.length}" value="${completed(l)}" style="width:100%;accent-color:#214b41" aria-label="${COURSE[l].name} course progress"></progress><p>${completed(l)>=COURSE[l].lessons.length?'All available conversation lessons completed. Keep practising without hints.':'Next: '+COURSE[l].lessons[Math.max(0,next(l))].goal}</p></section>`).join('')}</div><section class="card" style="margin-top:24px"><h2>Progress means being able to use it.</h2><p>Lesson completion records practice, not verified fluency. Ask yourself: can I understand the greeting, recall my answer, and say it without a hint?</p><button class="secondary" data-action="settings">Settings & progress backup</button></section>`;}
$('#main').innerHTML=html;}
function switcher(){return `<div class="switcher" aria-label="Choose language">${['fr','de'].map(l=>`<button data-language="${l}" class="${language===l?'selected':''}" aria-pressed="${language===l}">${COURSE[l].name}</button>`).join('')}</div>`;}
function knownWords(){let m=new Map();state.done[language].forEach(i=>COURSE[language].lessons[i]?.phrases.forEach(p=>m.set(p[0],p)));return [...m.values()];}
function say(t,l,slow=false){playModel(t,l,slow);}
function openLesson(l,i){if(!COURSE[l]?.lessons[i]){notice('That lesson is not available yet.');return;}stopRecording();resetSpeaking();active={l,i,d:COURSE[l].lessons[i]};step=0;phraseIndex=0;passed=false;listeningPassed=false;lessonRender();$('#lesson-dialog').showModal();}
function lessonRender(){let {l,i,d}=active;const stages=['Discover','Listen','Remember','Speak'];let body=`<div class="lesson-top"><button class="close" data-action="close" aria-label="Close lesson">×</button><p class="eyebrow">${COURSE[l].name} · DAY ${i+1} · ${stages[step]}</p><h2>${d.title}</h2><progress value="${step+1}" max="4" aria-label="Lesson stage"></progress></div>`;
if(step===0){let p=d.phrases[phraseIndex];body+=`<p>${d.goal}</p>${lessonPicture(d)}<div class="phrase"><p class="eyebrow">PHRASE ${phraseIndex+1} OF ${d.phrases.length}</p><p class="target" lang="${l}">${esc(p[0])}</p><p>${esc(p[1])}</p><div class="audio-row"><button class="secondary" data-say="${esc(p[0])}" data-lang="${l}">♬ Listen</button><button class="secondary" data-say="${esc(p[0])}" data-lang="${l}" data-slow="true">Slow + pauses</button></div></div><p>${esc(p[2])}</p><p class="muted">${esc(p[3])}</p>${d.grammar?`<details class="grammar-note"><summary>A little grammar</summary><p>${esc(d.grammar)}</p></details>`:''}<div class="lesson-actions"><button class="secondary" data-action="previous-phrase" ${phraseIndex===0?'disabled':''}>Previous</button><button class="primary" data-action="next-phrase">${phraseIndex<d.phrases.length-1?'Next phrase →':'Listen to a conversation →'}</button></div>`;}
if(step===1)body+=listeningMarkup(d,l);
if(step===2)body+=`<h3>${d.question}</h3><div class="choices">${d.options.map(o=>`<button class="choice" data-answer="${esc(o)}" lang="${l}">${esc(o)}</button>`).join('')}</div><p class="feedback" id="feedback" role="status">Choose your answer.</p>${writingMarkup(d,l)}${stageActions('Practise speaking →',!passed)}`;
if(step===3)body+=speakingMarkup(d,l);
$('#lesson-body').innerHTML=body;}
function stageActions(label,disabled=false){return `<div class="lesson-actions"><button class="secondary" data-action="back-stage">Back</button><button class="primary" data-action="next-stage" ${disabled?'disabled':''}>${label}</button></div>`;}
async function record(){if(recorder?.state==='recording'){recorder.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notice('Recording is unavailable here. You can still practise aloud.');return;}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!$('#lesson-dialog').open||step!==3){stream.getTracks().forEach(t=>t.stop());return;}const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{stream?.getTracks().forEach(t=>t.stop());if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));let a=$('#playback');if(a){a.src=recordUrl;a.hidden=false;$('#record-button').textContent='● Record again';$('#record-status').textContent='Listen back, then compare with the model.';}};recorder.start();$('#record-button').textContent='■ Stop recording';$('#record-status').textContent='Recording… click stop when finished.';}catch{notice('Microphone access was unavailable. Practise aloud, or allow access and retry.');}}
function stopRecording(){cancelSpeechCheck();cancelPlayback();if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());if(recordUrl){URL.revokeObjectURL(recordUrl);recordUrl=null;}if('speechSynthesis'in window)speechSynthesis.cancel();}
function finish(){if(step!==3||speechPassed.size!==active.d.phrases.length){notice('Check each speaking phrase before completing this lesson.');return;}let {l,i,d}=active;if(!state.done[l].includes(i))state.done[l].push(i);d.phrases.forEach(([p,e])=>{let key=l+':'+p;if(!state.reviews[key])state.reviews[key]={l,p,e,box:0,due:Date.now()};});save();stopRecording();$('#lesson-body').innerHTML=`<div class="completion"><div class="icon-tile">✓</div><p class="eyebrow">ONE SMALL STEP, TAKEN</p><h2>You showed up. You spoke.</h2><p>Day ${i+1} complete. Your phrases are ready for review.</p><button class="primary" data-action="close">Back to my learning space</button></div>`;render();}
let reviewKey=null;function review(){let items=due();if(!items.length){nav('words');notice('No phrases due yet. Complete a lesson or revisit your words.');return;}reviewKey=items[0][0];let r=items[0][1];$('#lesson-body').innerHTML=`<button class="close" data-action="close" aria-label="Close review">×</button><p class="eyebrow">RECALL · ${COURSE[r.l].name} · ${items.length} DUE</p><h2>How would you say this?</h2><div class="phrase"><p class="target">${esc(r.e)}</p><p id="review-answer" hidden lang="${r.l}">${esc(r.p)}</p></div><button class="secondary" data-action="reveal">Reveal answer</button><div id="review-rating" hidden><p>How well did you remember?</p><button class="secondary" data-rating="again">Let’s try again</button> <button class="primary" data-rating="good">I remembered</button></div>`;if(!$('#lesson-dialog').open)$('#lesson-dialog').showModal();}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view){nav(b.dataset.view);return;}if(b.dataset.language){language=b.dataset.language;render();return;}if(b.dataset.lesson){let [l,i]=b.dataset.lesson.split(':');openLesson(l,+i);return;}if(b.dataset.say){say(b.dataset.say,b.dataset.lang,b.dataset.slow==='true');return;}if(b.dataset.answer){let correct=b.dataset.answer===active.d.answer;b.classList.add(correct?'correct':'wrong');$('#feedback').textContent=correct?'That’s it! Now try saying it aloud.':'Not quite. Think about the situation and try again.';if(correct){passed=true;document.querySelector('[data-action="next-stage"]').disabled=false;}return;}if(b.dataset.rating){let r=state.reviews[reviewKey];if(b.dataset.rating==='good'){r.box=Math.min(5,r.box+1);r.due=Date.now()+[1,3,7,14,30,60][r.box-1]*86400000;}else{r.box=0;r.due=Date.now()+60000;}save();if(due().length)review();else{$('#lesson-dialog').close();render();notice('Review complete. Your next review is scheduled.');}return;}let a=b.dataset.action;if(a==='close')$('#lesson-dialog').close();if(a==='settings')openSettings();if(a==='review')review();if(a==='previous-phrase'){cancelPlayback();phraseIndex--;lessonRender();}if(a==='next-phrase'){cancelPlayback();if(phraseIndex<active.d.phrases.length-1)phraseIndex++;else step++;lessonRender();}if(a==='back-stage'){stopRecording();step--;lessonRender();}if(a==='next-stage'){if(step===1&&active.d.listening&&!listeningPassed)return;if(step===2&&!passed)return;cancelPlayback();if(step===3)finish();else{step++;lessonRender();}}if(a==='record')record();if(a==='reveal'){$('#review-answer').hidden=false;$('#review-rating').hidden=false;let r=state.reviews[reviewKey];say(r.p,r.l);}if(a==='video'){$('#video-slot').innerHTML='<iframe title="DW Nicos Weg A1 German film" src="https://www.youtube-nocookie.com/embed/4-eDoThe6qo" allow="encrypted-media; picture-in-picture" allowfullscreen></iframe>';b.disabled=true;}});
$('#lesson-dialog').addEventListener('close',stopRecording);
function openSettings(){$('#minutes').value=state.minutes;$('#settings-dialog').showModal();}$('#settings').onclick=openSettings;$('#settings-dialog').addEventListener('close',()=>{state.minutes=+$('#minutes').value;save();render();});$('#text-size').onclick=()=>{state.large=!state.large;save();render();};$('#export').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='bonjour-hallo-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import').onchange=async e=>{try{let s=JSON.parse(await e.target.files[0].text());if(![30,60,90].includes(s.minutes)||!s.done||!['fr','de'].every(l=>Array.isArray(s.done[l])&&s.done[l].every(i=>Number.isInteger(i)&&i>=0&&i<COURSE[l].lessons.length))||!s.reviews||!Object.values(s.reviews).every(r=>['fr','de'].includes(r.l)&&typeof r.p==='string'&&typeof r.e==='string'&&Number.isFinite(r.due)&&Number.isInteger(r.box)&&r.box>=0&&r.box<=5))throw Error();state={minutes:s.minutes,done:{fr:[...new Set(s.done.fr)],de:[...new Set(s.done.de)]},reviews:s.reviews,large:!!s.large};save();$('#minutes').value=state.minutes;$('#settings-status').textContent='Your progress has been restored.';render();}catch{$('#settings-status').textContent='That backup could not be read. Choose an exported Bonjour Hallo backup.';}};
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_language_lesson',title:'Start a language lesson',description:'Open a French or German lesson without marking it complete.',inputSchema:{type:'object',properties:{language:{type:'string',enum:['fr','de']},day:{type:'integer',minimum:1,maximum:Math.max(...Object.values(COURSE).map(c=>c.lessons.length))}},required:['language','day'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['fr','de'].includes(input.language)||!Number.isInteger(input.day)||input.day<1||input.day>COURSE[input.language].lessons.length)throw new Error('Choose fr or de and an available day from the course.');if($('#lesson-dialog').open)$('#lesson-dialog').close();openLesson(input.language,input.day-1);return {opened:true,language:input.language,day:input.day};}})).catch(()=>{});}catch{}}
